mapper.select:
SELECT c.id AS card_id, c.user_id AS user_id, u.name AS owner_name, u.role AS owner_role, COALESCE(linked_cp.id, matched_cp.id) AS card_product_id, COALESCE(linked_cp.company, matched_cp.company, c.company) AS company, COALESCE(c.card_name, linked_cp.name, matched_cp.name) AS card_name, COALESCE(linked_cp.annual_fee, matched_cp.annual_fee, 0) AS annual_fee, COALESCE(linked_cp.image, matched_cp.image) AS image, JSON_UNQUOTE(JSON_EXTRACT(COALESCE(linked_cp.benefit, matched_cp.benefit), '$')) AS benefit, COALESCE(linked_cp.`condition`, matched_cp.`condition`) AS condition_text, DATE_FORMAT(COALESCE(linked_cp.updated_at, matched_cp.updated_at), '%Y-%m-%d %H:%i:%s') AS condition_checked_at FROM card c INNER JOIN `user` u ON u.id = c.user_id LEFT JOIN card_product matched_cp ON matched_cp.id = ( SELECT cp2.id FROM card_product cp2 WHERE ( REPLACE(REPLACE(LOWER(COALESCE(cp2.company, '')), ' ', ''), '카드', '') = REPLACE(REPLACE(LOWER(COALESCE(c.company, '')), ' ', ''), '카드', '') OR REPLACE(REPLACE(LOWER(COALESCE(c.company, '')), ' ', ''), '카드', '') LIKE CONCAT('%', REPLACE(REPLACE(LOWER(COALESCE(cp2.company, '')), ' ', ''), '카드', ''), '%') OR REPLACE(REPLACE(LOWER(COALESCE(cp2.company, '')), ' ', ''), '카드', '') LIKE CONCAT('%', REPLACE(REPLACE(LOWER(COALESCE(c.company, '')), ' ', ''), '카드', ''), '%') ) AND REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(LOWER(COALESCE(cp2.name, '')), ' ', ''), '카드', ''), '-', ''), '_', ''), '.', ''), '/', ''), '[', ''), ']', '') = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(LOWER(COALESCE(c.card_name, '')), ' ', ''), '카드', ''), '-', ''), '_', ''), '.', ''), '/', ''), '[', ''), ']', '') ORDER BY cp2.updated_at DESC, cp2.id DESC LIMIT 1 ) AND c.card_product_id IS NULL LEFT JOIN card_product linked_cp ON linked_cp.id = c.card_product_id WHERE c.user_id IN
#{userId}
ORDER BY c.user_id ASC, COALESCE(linked_cp.company, matched_cp.company, c.company) ASC, COALESCE(c.card_name, linked_cp.name, matched_cp.name) ASC, c.id ASC

SELECT c.id AS card_id, GREATEST( COALESCE(SUM( CASE WHEN cr.type = 'EXPENSE' THEN cr.amount WHEN cr.type = 'INCOME' THEN -cr.amount ELSE 0 END ), 0), 0 ) AS recognized_performance_amount FROM card c LEFT JOIN card_record cr ON cr.card_id = c.id AND cr.record_date >= #{startDate} AND cr.record_date <= #{endDate} AND cr.type IN ('EXPENSE', 'INCOME') WHERE c.id IN
#{cardId}
GROUP BY c.id
